quired></div></div></form><div class="input-group mt-3"><input id="generatedLicenseKey" class="form-control" type="text" placeholder="La clé générée apparaîtra ici" readonly><button type="button" id="copyGeneratedLicenseBtn" class="btn btn-test" disabled><i class="fa fa-copy me-1"></i>Copier</button></div><div id="licenseResult" class="small text-white-50 mt-2" role="status"></div></div></div></div></div>
